const USAGE_NAMES={registered:'הרשמות',signed_in:'התחברויות',lesson_updated:'עדכוני שיעורים',completion_saved:'סימוני הכנה',question_asked:'שאלות למורה',answer_published:'תשובות שפורסמו',ocr_used:'זיהוי טקסט מצילומים',transcription_used:'תמלול הקלטות',ai_draft_used:'טיוטות AI',resource_attached:'צירוף מקורות',photo_attached:'צירוף צילומים'};
let managementTab='notifications',managementAccounts=[],managementSummary=null,managementScopeKey='',managementRequest=0,localUsage=[],localPolicies=[];
try{localUsage=JSON.parse(localStorage.getItem('homework-usage')||'[]');localPolicies=JSON.parse(localStorage.getItem('homework-notification-policies')||'[]')}catch{}
function notificationPolicy(schoolId){return(cloud.ready?cloud.notificationPolicies:localPolicies).find(p=>p.school_id===schoolId)||{school_id:schoolId,lesson_end_enabled:true,parent_updates_enabled:true,student_updates_enabled:true}}
async function trackUsage(action,targetClass=activeClassId()){if(!USAGE_NAMES[action])return;if(cloud.ready){if(!['ocr_used','transcription_used','ai_draft_used'].includes(action)||!targetClass)return;try{await cloudResult(cloud.client.rpc('record_school_usage',{usage_action:action,target_class:targetClass}))}catch{document.getElementById('managementStatus').textContent=t('לא ניתן לעדכן את נתוני השימוש כרגע.');}return}const event={id:crypto.randomUUID(),actor_id:role==='teacher'?school.teacherId:role+':'+activeStudentId(),school_id:school.classes.find(c=>c.id===targetClass)?.schoolId||activeSchoolId(),class_id:targetClass,action,source:'client',recorded_at:new Date().toISOString()};localUsage.push(event);localUsage=localUsage.slice(-3000);try{localStorage.setItem('homework-usage',JSON.stringify(localUsage))}catch{}}
function summarizeUsage(events,schoolId,since,totalAccounts){const selected=events.filter(e=>(!schoolId||e.school_id===schoolId)&&new Date(e.recorded_at)>=new Date(since));const units=new Map();for(const event of selected)units.set(event.action+':'+(event.session_key||event.id),event);const unique=[...units.values()];const counts={};unique.forEach(e=>counts[e.action]=(counts[e.action]||0)+1);return{activeUsers:new Set(selected.map(e=>e.actor_id)).size,logins:counts.signed_in||0,registrations:counts.registered||0,totalAccounts,types:Object.entries(counts).map(([action,count])=>({action,count})).sort((a,b)=>b.count-a.count)}}
function managementSchoolScope(){return role==='admin'&&document.getElementById('statsScope').value==='all'?null:activeSchoolId()}
function localAccountDirectory(scope){const users=roleUsers();return users.filter(u=>!scope||u.role==='manager'&&school.staff.some(s=>s.schoolId===scope&&s.userId===u.id)||school.staff.some(s=>s.schoolId===scope&&s.userId===u.id)||school.students.some(s=>s.id===u.id&&s.classIds.some(id=>school.classes.some(c=>c.id===id&&c.schoolId===scope)))||school.teachers.some(t=>t.id===u.id&&t.classIds.some(id=>school.classes.some(c=>c.id===id&&c.schoolId===scope)))).map(u=>({user_id:u.id,display_name:u.display_name,role:u.role,email:'',is_active:true,last_sign_in_at:null,created_at:null}))}
function renderAccountDirectory(){const list=document.getElementById('accountDirectory'),search=document.getElementById('accountSearch').value.trim().toLowerCase();list.replaceChildren();const users=managementAccounts.filter(u=>(u.display_name+' '+u.email).toLowerCase().includes(search));if(!users.length)list.append(el('p',t('אין חשבונות להצגה.')));for(const account of users){const row=el('div',null,'notice');row.append(userEl('b',account.display_name),userEl('div',account.email||''),el('div',t(ROLE_NAMES[account.role]||account.role)+' · '+t(account.is_active?'פעיל':'מושבת'),'meta'),el('div',t('כניסה אחרונה: ')+(account.last_sign_in_at?new Date(account.last_sign_in_at).toLocaleString(siteLocale()):t('לא נמדדה כניסה')),'meta'));if(role==='admin'&&account.role!=='admin'){const disable=el('button',t(account.is_active?'השבתת חשבון':'הפעלת חשבון'),'secondary');disable.type='button';disable.disabled=!cloud.ready;disable.onclick=async()=>{if(!confirm(t(account.is_active?'להשבית את החשבון בכלל המערכת?':'להפעיל מחדש את החשבון?')))return;try{await cloudResult(cloud.client.rpc('set_school_account_active',{target_user:account.user_id,enabled:!account.is_active}));await loadManagementData();document.getElementById('managementStatus').textContent=t('מצב החשבון עודכן.')}catch(e){document.getElementById('managementStatus').textContent=e.message}};row.append(disable)}list.append(row)}}
function renderUsageSummary(){const box=document.getElementById('usageStatistics');box.replaceChildren();if(!managementSummary){box.append(el('p',t('לחצו על רענון כדי לטעון נתונים.')));return}const cards=el('div',null,'stats');for(const [label,value] of [['חשבונות',managementSummary.totalAccounts],['משתמשים פעילים',managementSummary.activeUsers],['התחברויות',managementSummary.logins],['הרשמות',managementSummary.registrations]]){const card=el('div',null,'stat');card.append(el('b',String(value||0)),el('span',t(label)));cards.append(card)}box.append(cards);if(managementSummary.roleCounts?.length){box.append(el('h3',t('משתמשים לפי תפקיד')));for(const group of managementSummary.roleCounts)box.append(el('p',t(ROLE_NAMES[group.role]||group.role)+' · '+group.count));}box.append(el('h3',t('אופי השימוש במערכת')));if(!managementSummary.types.length)box.append(el('p',t('אין אירועי שימוש בטווח שנבחר.')));const max=Math.max(1,...managementSummary.types.map(x=>x.count));for(const type of managementSummary.types){const row=el('div');row.style.margin='12px 0';row.append(el('div',t(USAGE_NAMES[type.action]||type.action)+' · '+type.count));const bar=el('div');bar.style.cssText='height:10px;border-radius:6px;background:#7fa37d;width:'+Math.max(2,type.count/max*100)+'%';row.append(bar);box.append(row)}}
async function loadManagementData(){if(!['admin','manager'].includes(role))return;const id=++managementRequest,scope=managementSchoolScope(),since=new Date(Date.now()-Number(document.getElementById('statsPeriod').value)*86400000).toISOString();if(role!=='admin'&&!canAdminSchool(scope))return;try{if(cloud.ready){const [accounts,summary]=await Promise.all([loadAccountPages(scope),cloudResult(cloud.client.rpc('school_usage_summary',{target_school:scope,since_time:since}))]);if(id!==managementRequest)return;managementAccounts=accounts;managementSummary=summary;document.getElementById('managementStatus').textContent=t('נתוני השרת נטענו.');}else{managementAccounts=localAccountDirectory(scope);managementSummary=summarizeUsage(localUsage,scope,since,managementAccounts.length);const roles={};managementAccounts.forEach(a=>roles[a.role]=(roles[a.role]||0)+1);managementSummary.roleCounts=Object.entries(roles).map(([role,count])=>({role,count}));document.getElementById('managementStatus').textContent=t('הדגמה מקומית — אין התחברויות אמיתיות או חשבונות שרת.');}renderAccountDirectory();renderUsageSummary()}catch(e){if(id!==managementRequest)return;document.getElementById('managementStatus').textContent=t('טעינת הנתונים נכשלה: ')+e.message;managementSummary=null;renderUsageSummary()}}
function renderManagement(){const panel=document.getElementById('managementConsole');panel.hidden=!['admin','manager'].includes(role);if(panel.hidden)return;for(const [name,id] of [['notifications','manageNotifications'],['accounts','manageAccounts'],['statistics','manageStatistics']])document.getElementById(id).hidden=managementTab!==name;document.querySelector('#statsScope option[value="all"]').disabled=role!=='admin';if(role!=='admin')document.getElementById('statsScope').value='school';const policy=notificationPolicy(activeSchoolId());document.getElementById('policyLessonEnd').checked=policy.lesson_end_enabled;document.getElementById('policyParentUpdates').checked=policy.parent_updates_enabled;document.getElementById('policyStudentUpdates').checked=policy.student_updates_enabled;const history=document.getElementById('adminNotificationHistory');history.replaceChildren();const events=notificationState.events.filter(e=>school.classes.some(c=>c.id===e.classId&&c.schoolId===activeSchoolId())).slice(-20).reverse();history.append(el('h3',t('עדכונים אחרונים בבית הספר')));events.forEach(e=>history.append(el('p',e.title+' · '+e.body)));const scopeKey=role+':'+activeSchoolId()+':'+(cloud.ready?'cloud':'demo');if(scopeKey!==managementScopeKey){managementScopeKey=scopeKey;managementRequest++;managementAccounts=[];managementSummary=null;if(managementTab!=='notifications')loadManagementData()}renderAccountDirectory();renderUsageSummary()}
document.querySelectorAll('[data-management-tab]').forEach(button=>button.onclick=()=>{managementTab=button.dataset.managementTab;renderManagement();if(managementTab!=='notifications')loadManagementData()});document.getElementById('accountSearch').oninput=renderAccountDirectory;document.getElementById('refreshStatistics').onclick=loadManagementData;document.getElementById('statsPeriod').onchange=loadManagementData;document.getElementById('statsScope').onchange=loadManagementData;
document.getElementById('saveNotificationPolicy').onclick=async()=>{try{if(!canAdminSchool())throw new Error(t('אין הרשאה לבית הספר.'));const row={school_id:activeSchoolId(),lesson_end_enabled:document.getElementById('policyLessonEnd').checked,parent_updates_enabled:document.getElementById('policyParentUpdates').checked,student_updates_enabled:document.getElementById('policyStudentUpdates').checked};if(cloud.ready){await cloudResult(cloud.client.from('school_notification_settings').upsert(row,{onConflict:'school_id'}));await cloudRefresh()}else{localPolicies=localPolicies.filter(p=>p.school_id!==row.school_id);localPolicies.push(row);localStorage.setItem('homework-notification-policies',JSON.stringify(localPolicies));renderSchoolNotifications()}document.getElementById('managementStatus').textContent=t('מדיניות ההתראות נשמרה.')}catch(e){document.getElementById('managementStatus').textContent=e.message}};
document.getElementById('exportStatistics').onclick=()=>{if(!managementSummary)return;const lines=[['metric','count'],['accounts',managementSummary.totalAccounts],['active_users',managementSummary.activeUsers],['logins',managementSummary.logins],['registrations',managementSummary.registrations],...managementSummary.types.map(t=>[t.action,t.count])];const blob=new Blob(['\uFEFF'+lines.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='nohomework-usage-summary.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
renderManagement();

async function loadAccountPages(scope){const accounts=[];for(let start=0;start<10000;start+=200){const batch=await cloudResult(cloud.client.rpc('school_account_directory',{target_school:scope}).range(start,start+199));accounts.push(...batch);if(batch.length<200)return accounts;}document.getElementById('managementStatus').textContent=t('מוצגים עד 10000 חשבונות; הסטטיסטיקות כוללות את כולם.');return accounts}
